import 'package:pdf/pdf.dart'; import 'package:pdf/widgets.dart' as pw; import 'package:printing/printing.dart'; import 'package:intl/intl.dart'; import 'package:shopsmart_zw/services/db_service.dart'; import 'package:shopsmart_zw/services/auth_service.dart';
class ZimraExportService { Future<void> exportSalesReport(DateTime start, DateTime end) async { final db = await DBService.instance.database; final sales = await db.rawQuery("SELECT * FROM sales WHERE shop_id =? AND date BETWEEN? AND? ORDER BY date DESC", [AuthService.shopId, DateFormat('yyyy-MM-dd').format(start), DateFormat('yyyy-MM-dd').format(end)]);
  final pdf = pw.Document(); pdf.addPage(pw.MultiPage(pageFormat: PdfPageFormat.a4, build: (pw.Context context) => [pw.Header(level: 0, child: pw.Text('ShopSmart ZW - ZIMRA Sales Report')), pw.Text('Shop: ${AuthService.shopId}'), pw.Text('Period: ${DateFormat('dd/MM/yyyy').format(start)} to ${DateFormat('dd/MM/yyyy').format(end)}'), pw.SizedBox(height: 20),
    pw.Table.fromTextArray(headers: ['Date', 'Receipt', 'Cashier', 'Total \$', 'VAT \$', 'Payment'], data: sales.map((s) => [s['date'], s['receipt_number'], s['cashier'], s['total'], s['vat'], s['payment_method']]).toList()),
    pw.SizedBox(height: 20), pw.Text('Total Sales: \$${sales.fold(0.0, (sum, s) => sum + (s['total'] as double)).toStringAsFixed(2)}'), pw.Text('Total VAT 15.5%: \$${sales.fold(0.0, (sum, s) => sum + (s['vat'] as double)).toStringAsFixed(2)}'), pw.Text('**This report must be kept for 6 years per ZIMRA requirements**'), ]));
  await Printing.layoutPdf(onLayout: (format) => pdf.save()); }}
